};

function Y() {
	    if (typeof Y === 'undefined') return true;
      urlv = java.get('https://wnacg.date/',header).body()
    let regex = /<a\s+href="(.*www\..*\/)"/g;
    let urls = [];
    let match;
    while ((match = regex.exec(urlv))!== null) {
        urls.push(match[1]);
    }
v=String(source.getVariable());
var v=v.match(/^\d+$/)?v:0;
urlz=urls[v];
return urlz
 }
function login(b) {
  if (b == undefined) return true;
  info = result
  so = Y()
  pw = info.密码

  if (b) {
    url = so + 'users-check_login.html,'
    body = `normal=1&login_name=${encodeURI(info.用户名)}&login_pass=${pw}`}
  post = JSON.stringify({
    "body": String(body),
    "method": "POST"
  })
  url += post
  result = java.ajax(url)
